INT32 RemoveTxSStatus(RTMP_ADAPTER *pAd, UINT8 TxSPid, UINT8 *Type, UINT8 *PktPid, 
								UINT8 *PktType, UINT8 *PktSubType, UINT16 *TxRate, UINT32 *TxSPriv)
{
	TXS_CTL *TxSCtl = &pAd->TxSCtl;
	ULONG Flags;

	RTMP_SPIN_LOCK_IRQSAVE(&TxSCtl->TxSStatusLock, &Flags);

	if (TxSCtl->TxSStatus[TxSPid].State != TXS_USED) {
		RTMP_SPIN_UNLOCK_IRQRESTORE(&TxSCtl->TxSStatusLock, &Flags);
		return -1;
	}

	*Type = TxSCtl->TxSStatus[TxSPid].Type;
	*PktPid = TxSCtl->TxSStatus[TxSPid].PktPid;
	*PktType = TxSCtl->TxSStatus[TxSPid].PktType;
	*PktSubType = TxSCtl->TxSStatus[TxSPid].PktSubType;
	*TxRate = TxSCtl->TxSStatus[TxSPid].TxRate;
	*TxSPriv = TxSCtl->TxSStatus[TxSPid].Priv;
	/* Reserve callback ownership before releasing the PID. */
	if (*Type == TXS_TYPE1 && *PktType == FC_TYPE_MGMT &&
	    *PktSubType == SUBTYPE_BEACON && *TxSPriv < HW_BEACON_MAX_NUM) {
		if (TxSCtl->BeaconCallbacksInFlight[*TxSPriv] == 0xffffU) {
			RTMP_SPIN_UNLOCK_IRQRESTORE(&TxSCtl->TxSStatusLock, &Flags);
			return -1;
		}
		TxSCtl->BeaconCallbacksInFlight[*TxSPriv]++;
	}
	TxSCtl->TxSStatus[TxSPid].State = TXS_CLAIMED;
	RTMP_SPIN_UNLOCK_IRQRESTORE(&TxSCtl->TxSStatusLock, &Flags);

	return 0;
}
